package com.ecotrack.backend.simulation;
import com.ecotrack.backend.emission.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
@Service public class SimulationService{private final EmissionFactorRepository f;public SimulationService(EmissionFactorRepository f){this.f=f;}public SimulationDtos.Response simulate(SimulationDtos.Request r){String c=r.category().toUpperCase();EmissionFactor a=f.findFirstByCategoryAndActivityTypeAndActiveTrueOrderByIdDesc(c,r.currentType().toUpperCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current factor not found"));EmissionFactor b=f.findFirstByCategoryAndActivityTypeAndActiveTrueOrderByIdDesc(c,r.alternativeType().toUpperCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Alternative factor not found"));double ce=r.currentQuantity()*a.getFactor(),ae=r.alternativeQuantity()*b.getFactor(),save=ce-ae;double pct=ce==0?0:(save/ce)*100;return new SimulationDtos.Response(ce,ae,save,pct,save>=0?"The alternative can reduce estimated emissions.":"The alternative has higher estimated emissions.");}}
